void Export_Click(object s, RoutedEventArgs e)
{
    var t = Task.Run(() =>
    {
        var data = Build();
        Dispatcher.Invoke(() => status.Text = "почти готово");
        Save(data);
    });
    t.Wait();
    status.Text = "готово";
}

