async void Import_Click(object s, RoutedEventArgs e)
{
    var progress = new Progress<int>(p => bar.Value = p); // создан в UI-потоке
    await Task.Run(() => Import(files, progress));
    status.Text = "готово";
}

void Import(string[] files, IProgress<int> p)              // про окно ничего не знает
{
    for (int i = 0; i < files.Length; i++)
    {
        ImportFile(files[i]);
        p.Report((i + 1) * 100 / files.Length);             // Post в контекст UI
    }
}

